// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// GetChatMessages Read a cabal's chat channel.
	// (GET /v1/cabals/{id}/messages)
	GetChatMessages(ctx context.Context, request GetChatMessagesRequestObject) (GetChatMessagesResponseObject, error)
	// PostChatMessage Post a message to a cabal's chat.
	// (POST /v1/cabals/{id}/messages)
	PostChatMessage(ctx context.Context, request PostChatMessageRequestObject) (PostChatMessageResponseObject, error)
	// DeleteChatMessage Delete one of the caller's chat messages.
	// (DELETE /v1/cabals/{id}/messages/{message_id})
	DeleteChatMessage(ctx context.Context, request DeleteChatMessageRequestObject) (DeleteChatMessageResponseObject, error)
	// GetChatThread Read a chat thread.
	// (GET /v1/cabals/{id}/messages/{message_id}/thread)
	GetChatThread(ctx context.Context, request GetChatThreadRequestObject) (GetChatThreadResponseObject, error)
	// GetFeed Read the feed.
	// (GET /v1/feed)
	GetFeed(ctx context.Context, request GetFeedRequestObject) (GetFeedResponseObject, error)
	// GetFeedItem Read one feed item.
	// (GET /v1/feed/{id})
	GetFeedItem(ctx context.Context, request GetFeedItemRequestObject) (GetFeedItemResponseObject, error)
	// GetMeFeedMutes List feed mutes.
	// (GET /v1/me/feed-mutes)
	GetMeFeedMutes(ctx context.Context, request GetMeFeedMutesRequestObject) (GetMeFeedMutesResponseObject, error)
	// PutMeFeedMutes Mute a feed target.
	// (PUT /v1/me/feed-mutes)
	PutMeFeedMutes(ctx context.Context, request PutMeFeedMutesRequestObject) (PutMeFeedMutesResponseObject, error)
	// DeleteMeFeedMutesTargetTypeTargetID Unmute a feed target.
	// (DELETE /v1/me/feed-mutes/{target_type}/{target_id})
	DeleteMeFeedMutesTargetTypeTargetID(ctx context.Context, request DeleteMeFeedMutesTargetTypeTargetIDRequestObject) (DeleteMeFeedMutesTargetTypeTargetIDResponseObject, error)
	// CreateRealtimeToken Get a token request for live chat updates.
	// (POST /v1/realtime/token)
	CreateRealtimeToken(ctx context.Context, request CreateRealtimeTokenRequestObject) (CreateRealtimeTokenResponseObject, error)
	// DeleteUserFollow Unfollow a user.
	// (DELETE /v1/users/{id}/follow)
	DeleteUserFollow(ctx context.Context, request DeleteUserFollowRequestObject) (DeleteUserFollowResponseObject, error)
	// PostUserFollow Follow a user.
	// (POST /v1/users/{id}/follow)
	PostUserFollow(ctx context.Context, request PostUserFollowRequestObject) (PostUserFollowResponseObject, error)
	// GetUserFollowers List a user's followers.
	// (GET /v1/users/{id}/followers)
	GetUserFollowers(ctx context.Context, request GetUserFollowersRequestObject) (GetUserFollowersResponseObject, error)
	// GetUserFollowing List the users a user follows.
	// (GET /v1/users/{id}/following)
	GetUserFollowing(ctx context.Context, request GetUserFollowingRequestObject) (GetUserFollowingResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

